// `Selected: <n>` only shows once JavaScript runs, since it cannot update without it.
const mounted = ref(false)

// Keeps `Shared with me` current without disturbing anything else on the page (no reload, no refetch of the
// user's own notes). Polled often enough that an owner's change (share, unshare, rename, archive, restore,
// delete, or deleting their account) shows within 5 seconds.
const SHARED_POLL_MS = 2000
let sharedTimer: ReturnType<typeof setInterval> | null = null

async function pollShared() {
  try {
    const res = await $fetch<{ shared: SharedNote[] }>('/api/notes/shared')
    data.value = { ...data.value, shared: res.shared }
  } catch {
    // Transient errors are retried on the next tick.
  }
}

onMounted(() => {
  mounted.value = true
  sharedTimer = setInterval(pollShared, SHARED_POLL_MS)
})

onUnmounted(() => {
  if (sharedTimer) clearInterval(sharedTimer)
})

